#include <list>
#include <algorithm>

// Predicate: remove odd numbers
bool is_odd(int n) { return n % 2 != 0; }

int main() {
    std::list<int> l = {1, 4, 3, 8, 5, 2};

    // Remove all '4's
    l.remove(4); 
    // l is now {1, 3, 8, 5, 2}

    // Remove all odd numbers using predicate
    l.remove_if(is_odd); 
    // l is now {8, 2}

    // Using a lambda
    l.remove_if([](int n){ return n > 5; });
    // l is now {2}
}
